import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kt1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv3d for kernel (KH, KW, 1):
// For every (batch, slice-along-last-dim) image, a thread block computes a
// TH x TW tile of output pixels for OC_TILE output channels.
// The corresponding input tile (with halo) for ALL input channels is staged
// in shared memory, as are the weights, giving full data reuse across the
// OC_TILE output channels and the KHxKW taps.
constexpr int TH      = 16;
constexpr int TW      = 64;
constexpr int OC_TILE = 16;
constexpr int THREADS = TH * (TW / 4);  // 256

__global__ void conv3d_kt1_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int N, int C, int H, int W, int L,
    int OC, int KH, int KW,
    int stride, int pad, int dil,
    int Hout, int Wout, int Lout,
    int sh, int sw)
{
  extern __shared__ float smem[];
  float* sX = smem;                              // C * sh * sw
  const size_t xPad = ((size_t)C * sh * sw + 3) & ~(size_t)3;  // 16B align
  float* sW = smem + xPad;                       // C * KH * KW * OC_TILE (oc fastest)

  const int tid = threadIdx.x;

  // Block coordinates
  const int z      = blockIdx.z;                 // n * Lout + ol
  const int n      = z / Lout;
  const int ol     = z - n * Lout;
  const int il     = ol * stride - pad;          // input slice (kernel depth = 1)
  const bool lvalid = (il >= 0 && il < L);

  const int hTiles = (Hout + TH - 1) / TH;
  const int ht     = blockIdx.y % hTiles;
  const int ocTile = blockIdx.y / hTiles;
  const int wt     = blockIdx.x;

  const int oh0 = ht * TH;
  const int ow0 = wt * TW;
  const int ih_base = oh0 * stride - pad;
  const int iw_base = ow0 * stride - pad;

  // Global tensors (CuTe)
  auto mX = make_tensor(make_gmem_ptr(Xp),
      make_shape(N, C, H, W, L),
      make_stride((int64_t)C * H * W * L, (int64_t)H * W * L,
                  (int64_t)W * L, (int64_t)L, Int<1>{}));

  auto mW = make_tensor(make_gmem_ptr(Wp),
      make_shape(OC, C, KH, KW),
      make_stride((int64_t)C * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));

  auto mY = make_tensor(make_gmem_ptr(Yp),
      make_shape(N, OC, Hout, Wout, Lout),
      make_stride((int64_t)OC * Hout * Wout * Lout, (int64_t)Hout * Wout * Lout,
                  (int64_t)Wout * Lout, (int64_t)Lout, Int<1>{}));

  // Shared tensors (CuTe)
  auto sXt = make_tensor(make_smem_ptr(sX),
      make_shape(C, sh, sw),
      make_stride((int64_t)sh * sw, (int64_t)sw, Int<1>{}));

  // Weights staged transposed: output channel is the fastest (contiguous)
  // mode so the register-blocked inner loop can use vectorized loads.
  auto sWt = make_tensor(make_smem_ptr(sW),
      make_shape(C, KH, KW, Int<OC_TILE>{}),
      make_stride((int64_t)KH * KW * OC_TILE, (int64_t)KW * OC_TILE,
                  (int64_t)OC_TILE, Int<1>{}));

  // ---- Stage input tile (all channels, with halo) into shared memory ----
  const int xElems = C * sh * sw;
  for (int idx = tid; idx < xElems; idx += THREADS) {
    int c   = idx / (sh * sw);
    int rem = idx - c * sh * sw;
    int r   = rem / sw;
    int col = rem - r * sw;
    int ih  = ih_base + r;
    int iw  = iw_base + col;
    float v = 0.0f;
    if (lvalid && ih >= 0 && ih < H && iw >= 0 && iw < W) {
      v = mX(n, c, ih, iw, il);
    }
    sXt(c, r, col) = v;
  }

  // ---- Stage weights for this output-channel tile into shared memory ----
  const int wElems = C * KH * KW * OC_TILE;
  for (int idx = tid; idx < wElems; idx += THREADS) {
    int oc   = idx % OC_TILE;
    int rem  = idx / OC_TILE;
    int kw   = rem % KW;
    int rem2 = rem / KW;
    int kh   = rem2 % KH;
    int c    = rem2 / KH;
    int goc  = ocTile * OC_TILE + oc;
    float v = 0.0f;
    if (goc < OC) v = mW(goc, c, kh, kw);
    sWt(c, kh, kw, oc) = v;
  }
  __syncthreads();

  // ---- Compute: each thread computes FOUR output pixels along W ----
  // ---- (deeper register blocking) for OC_TILE output channels. ----
  // ---- Each staged float4 weight is loaded once per tap and ----
  // ---- reused for all four pixels, doubling the arithmetic ----
  // ---- per shared-memory weight load vs. the 2-pixel mapping. ----
  constexpr int PIX = 4;
  constexpr int TWR = TW / PIX;  // threads per output row
  const int r   = tid / TWR;
  const int col = tid - r * TWR;
  const int oh  = oh0 + r;
  int  ow[PIX];
  int  sc[PIX];
  bool v[PIX];
  bool anyV = (oh < Hout);
  #pragma unroll
  for (int p = 0; p < PIX; ++p) {
    ow[p] = ow0 + col + p * TWR;
    sc[p] = (col + p * TWR) * stride;
    v[p]  = (oh < Hout) && (ow[p] < Wout);
    anyV  = anyV || v[p];
  }
  if (anyV) {
    const int sr = r * stride;
    float acc[PIX][OC_TILE];
    #pragma unroll
    for (int p = 0; p < PIX; ++p) {
      #pragma unroll
      for (int oc = 0; oc < OC_TILE; ++oc) {
        const int goc = ocTile * OC_TILE + oc;
        const float bv = (Bp != nullptr && goc < OC) ? Bp[goc] : 0.0f;
        acc[p][oc] = bv;
      }
    }
    if (lvalid) {
      for (int c = 0; c < C; ++c) {
        for (int kh = 0; kh < KH; ++kh) {
          const int rr = sr + kh * dil;
          #pragma unroll 4
          for (int kw = 0; kw < KW; ++kw) {
            const int cw = kw * dil;
            float xv[PIX];
            #pragma unroll
            for (int p = 0; p < PIX; ++p) xv[p] = sXt(c, rr, sc[p] + cw);
            const float4* w4 =
                reinterpret_cast<const float4*>(&sWt(c, kh, kw, 0));
            #pragma unroll
            for (int q = 0; q < OC_TILE / 4; ++q) {
              const float4 wv = w4[q];
              #pragma unroll
              for (int p = 0; p < PIX; ++p) {
                acc[p][4 * q + 0] += xv[p] * wv.x;
                acc[p][4 * q + 1] += xv[p] * wv.y;
                acc[p][4 * q + 2] += xv[p] * wv.z;
                acc[p][4 * q + 3] += xv[p] * wv.w;
              }
            }
          }
        }
      }
    }
    #pragma unroll
    for (int p = 0; p < PIX; ++p) {
      if (v[p]) {
        #pragma unroll
        for (int oc = 0; oc < OC_TILE; ++oc) {
          const int goc = ocTile * OC_TILE + oc;
          if (goc < OC) mY(n, goc, oh, ow[p], ol) = acc[p][oc];
        }
      }
    }
  }
}

torch::Tensor conv3d_kt1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, L]");
  TORCH_CHECK(w.dim() == 5, "w must be [OC, C, KH, KW, 1]");
  TORCH_CHECK(w.size(4) == 1, "kernel size along last dim must be 1");
  TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0,
              "invalid stride/dilation/padding");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N  = x_c.size(0);
  const int64_t C  = x_c.size(1);
  const int64_t H  = x_c.size(2);
  const int64_t W  = x_c.size(3);
  const int64_t L  = x_c.size(4);
  const int64_t OC = w_c.size(0);
  const int64_t KH = w_c.size(2);
  const int64_t KW = w_c.size(3);
  TORCH_CHECK(w_c.size(1) == C, "w.size(1) must equal in_channels (groups=1)");

  const int64_t Hout = (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t Wout = (W + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  const int64_t Lout = (L + 2 * padding - 1) / stride + 1;  // kernel depth 1
  TORCH_CHECK(Hout > 0 && Wout > 0 && Lout > 0, "invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout, Lout}, x_c.options());

  const int sh = (int)((TH - 1) * stride + dilation * (KH - 1) + 1);
  const int sw = (int)((TW - 1) * stride + dilation * (KW - 1) + 1);
  const size_t xPad = ((size_t)C * sh * sw + 3) & ~(size_t)3;
  const size_t smem_bytes =
      (xPad + (size_t)OC_TILE * C * KH * KW) * sizeof(float);

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kt1_kernel,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)smem_bytes);
  }

  const int64_t wTiles  = (Wout + TW - 1) / TW;
  const int64_t hTiles  = (Hout + TH - 1) / TH;
  const int64_t ocTiles = (OC + OC_TILE - 1) / OC_TILE;

  dim3 block(THREADS);
  dim3 grid((unsigned)wTiles,
            (unsigned)(hTiles * ocTiles),
            (unsigned)(N * Lout));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv3d_kt1_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)W, (int)L,
      (int)OC, (int)KH, (int)KW,
      stride, padding, dilation,
      (int)Hout, (int)Wout, (int)Lout,
      sh, sw);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kt1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_kt1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kt1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution with kernel (kernel_size, kernel_size, 1),
    implemented with a single cooperative-tiled CuTe CUDA kernel.
    The nn.Conv3d module is kept only as the parameter container so that
    initialization and state_dict match the reference model exactly.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "ModelNew supports groups == 1 only"
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                (kernel_size, kernel_size, 1),
                                stride=stride, padding=padding,
                                dilation=dilation, groups=groups, bias=bias)
        self._ext = conv3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv3d.bias if self.conv3d.bias is not None else None
        return self._ext.conv3d_kt1_forward(
            x.contiguous(),
            self.conv3d.weight.contiguous(),
            bias,
            self.stride,
            self.padding,
            self.dilation,
        )

