  // ---- Compute: each thread computes TWO output pixels along W ----
  // ---- (register blocking) for OC_TILE output channels. Each ----
  // ---- staged float4 weight is loaded once per tap and reused ----
  // ---- for both pixels, doubling arithmetic per smem load. ----
  constexpr int TW2 = TW / 2;
