  const int col  = tid - r * TW2;
  const int oh   = oh0 + r;
  const int owA  = ow0 + col;
  const int owB  = ow0 + col + TW2;
  const bool vA = (oh < Hout) && (owA < Wout);
  const bool vB = (oh < Hout) && (owB < Wout);
