              accB[4 * q + 1] += xvB * wv.y;
              accB[4 * q + 2] += xvB * wv.z;
              accB[4 * q + 3] += xvB * wv.w;
            }
          }
        }
      }
    }
    #pragma unroll
    for (int oc = 0; oc < OC_TILE; ++oc) {
      const int goc = ocTile * OC_TILE + oc;
      if (goc < OC) {
        if (vA) mY(n, goc, oh, owA, ol) = accA[oc];
        if (vB) mY(n, goc, oh, owB, ol) = accB[oc];
